#include "simulation.hpp"
#include <iostream>
#include <stdexcept>
using namespace ofo;
void need(bool b,const char*m){if(!b)throw std::runtime_error(m);}
int main(){try{Geometry g;g.materials.push_back({"ground"});Mesh mesh;for(Vec p:std::vector<Vec>{{-100,0,-100},{100,0,-100},{100,0,100},{-100,0,100}}){Vertex v;v.position=p;mesh.vertices.push_back(v);}mesh.indices={0,2,1,0,3,2};g.meshes.push_back(mesh);VehicleConfig c;c.mass=1000;c.inertia={1000,1000,1000};c.lo={-.8f,-.25f,-1.5f};c.hi={.8f,.3f,1.5f};c.ratios={3,2,1.5f,1};c.engine_torque=0;c.torque_curve={{1000,1},{7000,1}};int i=0;for(auto&w:c.wheels){w.mount={(i%2?1:-1)*.7f,-.2f,(i<2?1:-1)*1.1f};w.rest=.4f;w.radius=.3f;i++;}
 Simulation idle(g,c,translate({0,1,0}));for(int k=0;k<500;k++)idle.step({});need(idle.state().damage==0,"idle gravity/suspension must not add damage");need(!idle.state().impacts||idle.state().impacts->empty(),"idle support must not dent body");
 Simulation fall(g,c,translate({0,12,0}));for(int k=0;k<500;k++)fall.step({});need(fall.state().damage>.1f,"actual solver impact must drive engine damage");auto impacts=fall.state().impacts;need(impacts&&!impacts->empty()&&impacts->size()<=32,"solver impact publishes bounded persistent body dents");for(const auto&impact:*impacts){need(impact.impulse>0&&impact.depth>0&&impact.radius>0,"dent requires positive solved contact impulse");need(std::isfinite(impact.position.x)&&std::isfinite(impact.normal.y),"contact converted to finite car local space");}auto before=fall.state().damage;fall.recover();need(fall.state().impacts==impacts,"recover preserves local dents with existing engine damage");need(!impacts->empty(),"replay contact snapshots remain immutable after recover");need(fall.state().damage==before,"recover does not repair engine");Simulation restart(g,c,translate({0,1,0}));need(restart.state().damage==0,"new race resets damage");VehiclePanelDefinition panel;panel.name="test_impact_panel";panel.mass=10;panel.lo=c.lo;panel.hi=c.hi;panel.center=(c.lo+c.hi)*.5f;panel.break_impulse=1;panel.unlock_impulse=1;Simulation parts(g,c,translate({0,12,0}),{panel});bool detached=false;for(int k=0;k<500;k++){parts.step({});auto state=parts.state();if(state.panels)for(auto&p:*state.panels)detached=detached||p.detached;}need(detached,"actual solver impact feeds native part detachment pipeline");const auto debris=parts.state().panels;
 parts.recover();
 need(debris&&!debris->empty()&&parts.state().panels&&!parts.state().panels->empty(),"recovery preserves detached panels");
 need(parts.state().panels->front().detached&&parts.state().panels->front().transform==debris->front().transform,"detached part remains where it fell");std::cout<<"actual Bullet impact damage="<<before<<"; idle/recover/restart passed\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
